use vstd::prelude::*;

verus! {
    spec fn is_ascii_letter(c: char) -> bool {
        (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
    }

    fn check_if_last_char_is_a_letter(txt: &str) -> bool
        requires
            txt.len() > 0,
        ensures
            (is_ascii_letter(txt.chars().last().unwrap()) && 
             (txt.len() == 1 || txt.chars().nth(txt.len() - 2).unwrap() == ' ')) 
             ==> result == true,
            (!is_ascii_letter(txt.chars().last().unwrap()) || 
             (txt.len() > 1 && txt.chars().nth(txt.len() - 2).unwrap() != ' ')) 
             ==> result == false,
    {
        let len = txt.len();
        let last_char = txt.chars().last().unwrap();
        
        if is_ascii_letter(last_char) {
            if len == 1 {
                return true;
            } else {
                let second_last_char = txt.chars().nth(len - 2).unwrap();
                return second_last_char == ' ';
            }
        }
        false
    }
}
